def seed_site_settings(apps, schema_editor):
    """Seed the axes, the approved enquiry address, and null category slots.

    Existing project keys (typology, underCreatech, and the rest) are copied
    through. Discipline and segment stay null until the studio chooses them.
    """
    from arch_media.content_migrate import (
        DEFAULT_ENQUIRY_RECIPIENT,
        SEEDED_CATEGORIES,
        add_project_category_slots,
        instagram_url_from_chrome,
    )

    Category = apps.get_model("arch_media", "Category")
    EnquiryRecipient = apps.get_model("arch_media", "EnquiryRecipient")
    SiteSettings = apps.get_model("arch_media", "SiteSettings")
    SiteChrome = apps.get_model("arch_media", "SiteChrome")
    ChromeVersion = apps.get_model("arch_media", "ChromeVersion")

    for name, slug, kind, order in SEEDED_CATEGORIES:
        Category.objects.get_or_create(
            slug=slug,
            defaults={"name": name, "kind": kind, "order": order, "active": True},
        )
    EnquiryRecipient.objects.get_or_create(
        email=DEFAULT_ENQUIRY_RECIPIENT,
        defaults={"active": True},
    )

    url = ""
    chrome = SiteChrome.objects.filter(key="default").first()
    if chrome is not None:
        url = instagram_url_from_chrome(chrome.data)
        updated, changed = add_project_category_slots(chrome.data)
        if changed:
            chrome.data = updated
            chrome.save(update_fields=["data"])
    SiteSettings.objects.get_or_create(key="default", defaults={"instagram_url": url})

    for version in ChromeVersion.objects.all():
        updated, changed = add_project_category_slots(version.data)
        if changed:
            version.data = updated
            version.save(update_fields=["data"])


